skinparam backgroundColor #FEFEFE
skinparam defaultFontSize 12

title الهندسة — اثنان من اشتراكات Ollama Cloud Pro على جهاز واحد
left to right direction

node &quot;آلتي الفيزيائية&quot; {
  frame &quot;Ollama مثيل A (الأصلي)
المنفذ :11434&quot; as Native {
    database &quot;هوية أ
/usr/share/ollama/.ollama/id_ed25519&quot;
  }
  frame &quot;Ollama مثيل B (Docker)
منفذ :11435&quot; as Docker {
    database &quot;الهوية ب
~/ollama-b-data/id_ed25519&quot;
  }
}

cloud &quot;أولماما سحابة&quot; {
  actor &quot;الحساب برو أ\n(البريد الإلكتروني 1)&quot; as A
  actor &quot;الحساب الاحترافي B
(البريد الإلكتروني 2)&quot; as B
}

Native --&amp;gt; A : &quot;مفتاح الجهاز A&quot;
Docker --&amp;gt; B : &quot;مفتاح الجهاز B&quot;

note bottom of Docker
  Conteneur Docker isolé :
  - Clé SSH distincte
  - Port réseau distinct (11435)
  - Volume persistant (~/ollama-b-data)
  - restart: always
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;النمط بسيط :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;إنشاء حجم`~/ollama-b-data`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;تشغيل حاوية دُوكر`ollama/ollama:0.20.2`مُعَيَّن على`11435:11434`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;استرداد مفتاح SSH من الحاوية → احفظه على ollama.com&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;فعل`ollama signin`مع بريد إلكتروني ثاني&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ضبط OpenCode مع موفّرين (`ollama`على :11434,`ollama-b`على :11435)&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;حسابان، بطاقة زرقاء، لا يوجد صراع.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ما_لا_يقيسه_التدقيق&quot;&gt;ما لا يقيسه التدقيق&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 40%;&quot;&gt;
&lt;col style=&quot;width: 60%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;نقطة عمياء&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;تأثير&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;جودة الكود المنتج&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;2,6 مليار توكن لا تشير إلى ما إذا كان الكود يتم تجميعه. جلساتي الثمانية باستخدام DeepSeek V4 Pro لديها معدل first-shot &amp;gt;90%&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;نظام إيكولوجي OpenCode&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;واجهة سطر الأوامر (CLI) مجانية، لكن قيمتها (الوكلاء، بيئات اختبار، السجل، تخزين مؤقت للرسائل) هائلة. ليست مشمولة في سعر الاشتراك — إنها أداة منفصلة.&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;كلفة الفرصة البديلة&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;قضاء ساعتين يوميًا لتصحيح هلوسات نموذج أقل يكلف أكثر من 20 يورو/شهر.&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;راحة البال&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;الاشتراك الثابت = لا مفاجأة. مع الدفع لكل رمز، يمكن أن يسبب ارتفاع النشاط أضرارًا جسيمة.&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;div class=&quot;admonitionblock warning&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-warning&quot; title=&quot;⚠️&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;الأسعار المذكورة هي تلك الخاصة بشهر مايو 2026. بعد ستة أشهر، سينخفض كل شيء. لكن نسبة القوة الهيكلية — الاشتراك الثابت مقابل الدفع حسب الاستخدام — ستظل مواتية للاشتراك للمستهلكين الكبار.&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_الخلاصة_حكم_الأرقام&quot;&gt;الخلاصة : حكم الأرقام&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;بعد 73 يومًا، و1 022 جلسة OpenCode، و2,6 مليار توكن:&lt;/p&gt;
&lt;/div&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 60%;&quot;&gt;
&lt;col style=&quot;width: 40%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;مترية&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;حكم&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
