&lt;p&gt;&lt;a href=&quot;0118_matrice_gouvernance_llm_zone_acces_workspace_post.html&quot;&gt;المادة 0117 — مصفوفة حوكمة LLM&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;0114_gouvernance_cercles_confiance_ontologie_spatiale_alignement_llm_post.html&quot;&gt;المادة 0114 — دوائر الثقة&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;0116_compartimentage_epistemique_automatise_llm_post.html&quot;&gt;المادة 0116 — التقسيم المعرفي الآلي&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;0108_gouvernance_agent_opcode_eager_lazy_post.html&quot;&gt;المادة 0108 — حوكمة الوكيل الذكي باستخدام AsciiDoc&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
