&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;`gitPropertiesPluginVersion`غير متوافق مع Java 21&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;2.5.7&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
