&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_الدورة_الكاملة_لحياة_الوظيفة&quot;&gt;الدورة الكاملة لحياة الوظيفة&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;Failed to generate image: PlantUML preprocessing failed: [From &amp;lt;input&amp;gt; (line 8) ]

@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontName sans-serif

title دورة حياة كاملة لوظيفة شل
state &quot;غير موجود&quot; as none
state &quot;الواجهة الأمامية\n(يشغل الطرفي)&quot; as foreground #LightCoral
state &quot;معلق
^^^^^
 Syntax Error? (Assumed diagram type: state)

@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontName sans-serif

title دورة حياة كاملة لوظيفة شل
state &quot;غير موجود&quot; as none
state &quot;الواجهة الأمامية\n(يشغل الطرفي)&quot; as foreground #LightCoral
state &quot;معلق
(Ctrl+Z / SIGTSTP)&quot; as suspended #LightYellow
state &quot;الخلفية
(bg أو &amp;amp;)&quot; as background #LightGreen
state &quot;مكتمل\n(كود الخروج 0)&quot; as done #LightGray

[*] --&amp;gt; none
none --&amp;gt; foreground : tape une commande
foreground --&amp;gt; suspended : Ctrl+Z
foreground --&amp;gt; done : fin normale

suspended --&amp;gt; foreground : fg
suspended --&amp;gt; background : bg
suspended --&amp;gt; done : kill %n

background --&amp;gt; foreground : fg
background --&amp;gt; done : fin normale\n(en arrière-plan)
background --&amp;gt; suspended : Ctrl+Z\n(si fg puis Ctrl+Z)

done --&amp;gt; [*]

note right of suspended
  L&#39;état suspendu est
  le pivot de tout le
  système de jobs
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_نصائح_متقدمة&quot;&gt;نصائح متقدمة&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ذكرأنثى_مع_الجوب_الأحدث_والتناوب&quot;&gt;ذكر/أنثى مع الجوب الأحدث والتناوب&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;code&gt;fg`بدون حجة يعيد تشغيل المهمة المحددة&lt;/code&gt;+&lt;code&gt;(الأحدث). لكنك يمكنك أيضًا استخدام&lt;/code&gt;%-`لاستهداف الوظيفة السابقة :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ vim file1.txt
^Z
[1]+  Stoppé    vim file1.txt

$ vim file2.txt
^Z
[2]+  Stoppé    vim file2.txt

$ fg      # ramène job [2] (le plus récent)
$ fg %-   # ramène job [1] (le précédent)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_إنهاء_مهمة_بشكل_صحيح&quot;&gt;إنهاء مهمة بشكل صحيح&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ jobs
[1]-  Stoppé    vim config.yml
[2]+  Stoppé    ./gradlew test

$ kill %2       # envoie SIGTERM au job 2
$ kill -9 %1    # envoie SIGKILL au job 1 (force)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_désown_فصل_عن_القشرة&quot;&gt;désown : فصل عن القشرة&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;code&gt;disown`يزيل وظيفة من جدول وظائف القذيفة. تستمر العملية في التشغيل لكن لا يمكن إعادتها مع`fg&lt;/code&gt; :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ ./gradlew build &amp;amp;
[1] 12345

$ disown %1
# Le processus continue mais n&#39;est plus lié au shell
# Ça survives à la fermeture du terminal&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_دمج_مع_nohup_للعمليات_الطويلة&quot;&gt;دمج مع nohup للعمليات الطويلة&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;لتبقى العملية تعمل بعد إغلاق الطرفي :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ nohup ./gradlew build &amp;amp;
[1] 12345
$ disown %1
# Le build continue même si vous fermez le terminal&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;Failed to generate image: PlantUML preprocessing failed: [From &amp;lt;input&amp;gt; (line 7) ]

@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontName sans-serif

rectangle &quot;fg&quot; as fg_ #SkyBlue {
  card &quot;أَحضر الوظيفة
الأحدث (+)&quot; as f1
^^^^^
 Syntax Error? (Assumed diagram type: activity)

@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontName sans-serif

rectangle &quot;fg&quot; as fg_ #SkyBlue {
  card &quot;أَحضر الوظيفة
الأحدث (+)&quot; as f1
  card &quot;استهدف وظيفة
محددة: fg %n&quot; as f2
  card &quot;يُبدل : fg %-&quot; as f3
}

rectangle &quot;قتل %n&quot; as kill_ #LightCoral {
  card &quot;SIGTERM (نظيف)&quot; as k1
  card &quot;SIGKILL -9 (قسراً)&quot; as k2
}

rectangle &quot;يتبرأ&quot; as disown #Lavender {
  card &quot;افصل عن القشرة
(يبقى بعد قطع الاتصال)&quot; as d1
}

rectangle &quot;nohup + &amp;amp;&quot; as nohup_ #LightGreen {
  card &quot;العملية المحصنة
ضد SIGHUP
(يستمر رغم الإغلاق
من terminal)&quot; as n1
}

fg_ -right-&amp;gt; kill_ : si faut\nterminer
kill_ -right-&amp;gt; disown_ : ou détacher
nohup_ -left-&amp;gt; fg_ : fg ramène en\navant-plan

note bottom of disown_
  Après disown, fg ne peut
  plus ramener le job
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_المصائد_والأخطاء_الشائعة&quot;&gt;المصائد والأخطاء الشائعة&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_الخلط_بين_ctrlz_و_ctrlc&quot;&gt;الخلط بين Ctrl+Z و Ctrl+C&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;هذا هو الخطأ الأكثر شيوعًا.`Ctrl+C`يقتل العملية.`Ctrl+Z`يوقفه. إذا ضغطت على`Ctrl+C`كرد فعل، كل الحالة ضاعت — ملفات مفتوحة، جلسات LLM، البناءات جارية.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;./images/ctrlz-vs-ctrlc.svg&quot; alt=&quot;ctrlz vs ctrlc&quot; width=&quot;938&quot; height=&quot;129&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_الوظائف_محلية_إلى_الغلاف&quot;&gt;الوظائف محلية إلى الغلاف&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;code&gt;jobs&lt;/code&gt;, &lt;code&gt;fg&lt;/code&gt; et `bg`تعمل فقط في الشل الذي أطلق فيه العمليات. إذا فتحت طرفية جديدة، فلن ترى وظائف الشل الآخر.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Terminal 1
$ vim file.txt
^Z
[1]+  Stoppé    vim file.txt

# Terminal 2 (nouveau)
$ jobs
# (rien — les jobs sont locaux au shell)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;لرؤية عمليات النظام على مستوى النظام، استخدم`ps` ou &lt;code&gt;htop&lt;/code&gt;:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;ps aux | grep vim&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_الوظائف_لا_تستمر_بعد_إغلاق_القشرة&quot;&gt;الوظائف لا تستمر بعد إغلاق القشرة&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;إذا أغلقت المحطة، تُدمّر جميع الوظائف المعلقة أو التي تعمل في الخلفية. لكي يبقى عملية على قيد الحياة، استخدم`nohup`+&lt;code&gt;disown&lt;/code&gt;:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ nohup ./gradlew build &amp;amp;
[1] 12345
$ disown %1
# Fermer le terminal → le build continue&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_العمليات_التفاعلية_fg&quot;&gt;العمليات التفاعلية fg&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;بعض البرامج التفاعلية لا تسير على ما يرام بعد`Ctrl+Z`+&lt;code&gt;fg&lt;/code&gt;. إنه نادر لكن يحدث :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;بعض البرامج التي تستخدم الإشارات (vim, htop, less) تعاملها جيدًا`Ctrl+Z`)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;البرامج الشبكية الطويلة (ssh, opencode) تسترجع عادةً بشكل صحيح&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;البرامج التي تُعدّل الطرفيّة (ncurses) قد تترك أحيانًا الطرفيّة في حالة غير متوقّعة&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;في حالة جهاز معطوب بعد`fg`، اكتب :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;reset&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
