التكبير مقابل حجم الخط&quot; as css #LightYellow {
    card &quot;zoom &amp;gt; font-size\n للقائمة المكونات&quot; as c1
    card &quot;تجاوز جافاسكريبت للتخطيط
الارتفاع/ارتفاع السطر&quot; as c2
    card &quot;امتداد Custom CSS
 يتطلب تفعيل يدوي
  (Ctrl+Shift+P)&quot; as c3
}

rectangle &quot;**الأتمتة**
سكربت التحديث&quot; as auto #LightCoral {
    card &quot;إعادة تصحيح CSS بعد\n كل تحديث&quot; as a1
    card &quot;حذف checksums\n product.json&quot; as a2
    card &quot;النسخ الاحتياطي بتاريخ ووقت
 قبل الاستبدال&quot; as a3
}

install -right-&amp;gt; css : ensuite
css -right-&amp;gt; auto : enfin

note top of install
  Contrôle total sans élévation
  de privilèges
end note

note top of auto
  Sans script, chaque MAJ
  efface les patches CSS
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_التثبيت_في_المنزل_يحرر_كل_شيء&quot;&gt;التثبيت في المنزل يحرر كل شيء&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;تثبيت محلي في`~/apps`يمنح تحكمًا كاملاً على VS Code :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;لا`sudo`لتعديل CSS أو الإعداد&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;يمكن للوكيل opencode+LLM الكتابة في ملفات الإعداد وأصول بيئة التطوير المتكاملة&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;تراجع بسيط : استعادة النسخة الاحتياطية الموقوتة&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_zoom_font_size_للمكونات_القائمة&quot;&gt;zoom` &amp;gt; &lt;code&gt;font-size&lt;/code&gt; للمكونات القائمة&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;VS Code يتحكم في ارتفاع الأسطر عبر JavaScript. عدّل`font-size`بدون القدرة على لمس الارتفاع المخصص من قبل محرك التخطيط يؤدي إلى نصوص تتجاوز الحدود. الخاصية`zoom`على الحاوية الأم، يتم تكبير كل شيء بشكل متناسب ويتجنب هذه المشكلة.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_امتداد_custom_css_يتطلب_تفعيلًا_صريحًا&quot;&gt;امتداد Custom CSS يتطلب تفعيلًا صريحًا&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;هذا ليس معلمة &quot;set and forget&quot;. كل تعديل على ملف CSS المخصص يتطلب إعادة تنفيذ &quot;Enable Custom CSS and JS&quot; من لوحة الأوامر (&lt;code&gt;Ctrl+Shift+P&lt;/code&gt;).&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_سكريبت_التحديث_ضروري&quot;&gt;سكريبت التحديث ضروري&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;بدون نص برمجي، كل تحديث لـ VS Code يمسح تصحيحات CSS الخاصة بـ Workbench. النص البرمجي`vscode-update.sh`يعمل على أتمتة التنزيل، والاستبدال، وإعادة التصحيح، وتنظيف مجاميع التحقق.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مراجع_سريعة&quot;&gt;مراجع سريعة&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;تنزيل VS Code : &lt;a href=&quot;https://code.visualstudio.com/Download&quot; class=&quot;bare&quot;&gt;https://code.visualstudio.com/Download&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ملحق محمل CSS و JS مخصص :`be5invis.vscode-custom-css`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;مشكلة VS Code تطلب إعدادًا أصليًا لخط المستكشف :https://github.com/microsoft/vscode/issues/149[github.com/microsoft/vscode#149]&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

