  note right
    ✓ Développement en jours
    ✓ Coût : 0€
    ✓ Validation concept
  end note
}

rectangle &quot;المرحلة 2: النمو&quot; #LightYellow {
  component &quot;JBake + Supabase
+ Spring Boot (اختياري)&quot; as growth
  note right
    ✓ Logique métier émerge
    ✓ Premiers jobs planifiés
    ✓ Intégrations tierces
  end note
}

rectangle &quot;**المرحلة 3 : التوسع**&quot; #LightCoral {
  component &quot;الهندسة المعمارية الكاملة&quot; as scale
  note right
    ✓ Orchestration complexe
    ✓ Performances optimisées
    ✓ Cache distribué
  end note
}

mvp -down-&amp;gt; growth : Quand la complexité\nle justifie
growth -down-&amp;gt; scale : Optimisation\ncontinue
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;لا تقم ببناء Spring Boot إذا لم تكن بحاجة إليه.&lt;/strong&gt;ابدأ مع Supabase، أضف Spring Boot عندما يبرر التعقيد ذلك.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_المبدأ_2_فصل_حسب_طبيعة_العملية&quot;&gt;المبدأ 2: فصل حسب طبيعة العملية&lt;/h3&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;operation-types.svg&quot; alt=&quot;operation types&quot; width=&quot;1266&quot; height=&quot;241&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_المبدأ_3_مصدر_واحد_للحقيقة&quot;&gt;المبدأ 3 : مصدر واحد للحقيقة&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;Failed to generate image: PlantUML preprocessing failed: [From &amp;lt;input&amp;gt; (line 17) ]

@startuml
skinparam backgroundColor #FEFEFE

database &quot;PostgreSQL&quot; as db #LightGray {
  package &quot;المخطط: auth (Supabase)&quot; #LightGreen {
    [users]
    [sessions]
    [identities]
  }

  package &quot;المخطط: عام (مشارك)&quot; #SkyBlue {
    [articles]
    [comments]
    [profiles]
  }

  package &quot;أنت مترجم محترف.
^^^^^
 Syntax Error? (Assumed diagram type: component)

@startuml
skinparam backgroundColor #FEFEFE

database &quot;PostgreSQL&quot; as db #LightGray {
  package &quot;المخطط: auth (Supabase)&quot; #LightGreen {
    [users]
    [sessions]
    [identities]
  }

  package &quot;المخطط: عام (مشارك)&quot; #SkyBlue {
    [articles]
    [comments]
    [profiles]
  }

  package &quot;أنت مترجم محترف.
ترجم من fr إلى ar.
احفظ جميع أجزاء الكود المضمنة بين علامتي تنصيص (`...`) كما هي — لا تعدل محتوى العلامة أو مسافة أو موضعها.
قد يكون هذا النص جزءًا من جملة أكبر — ترجم هذا الجزء دون طلب سياق إضافي.
أخرج النص المترجم فقط — لا شرح، لا تعليق، لا مقدمة، لا بدائل، لا خيارات.
النموذج: الأعمال (Spring Boot)&quot; #Coral {
    [orders]
    [payments]
    [reports]
  }
}

component &quot;سوبابيس&quot; as supabase #LightGreen
component &quot;سبرينج بوت&quot; as spring #Coral

supabase -down-&amp;gt; users : Gère
supabase -down-&amp;gt; sessions : Gère
supabase -down-&amp;gt; articles : Accède
supabase -down-&amp;gt; comments : Accède
supabase -down-&amp;gt; profiles : Accède

spring -down-&amp;gt; articles : Accède
spring -down-&amp;gt; profiles : Accède
spring -down-&amp;gt; orders : Gère
spring -down-&amp;gt; payments : Gère
spring -down-&amp;gt; reports : Gère

note right of db
  **Avantages :**
  • Pas de synchronisation complexe
  • JOINs possibles entre tables
  • Cohérence garantie
  • Migrations unifiées
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;من خلال مشاركة نفس مثيل PostgreSQL، يعمل Supabase و Spring Boot على نفس البيانات دون مزامنة معقدة.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_تنظيم_التدفقات&quot;&gt;تنظيم التدفقات&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_التدفق_1_المصادقة_المركزية&quot;&gt;التدفق 1 : المصادقة المركزية&lt;/h3&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;auth-orchestration.svg&quot; alt=&quot;auth orchestration&quot; width=&quot;1089&quot; height=&quot;950&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;نقطة رئيسية&lt;/strong&gt;: عملية مصادقة واحدة، ومفتاح JWT واحد، يمكن استخدامه في كل مكان.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_التدفق_2_تنظيم_عملية_عمل_معقدة&quot;&gt;التدفق 2: تنظيم عملية عمل معقدة&lt;/h3&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;business-orchestration.svg&quot; alt=&quot;business orchestration&quot; width=&quot;1112&quot; height=&quot;990&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;ما يقدمه Spring Boot&lt;/strong&gt;: تنسيق موثوق للعمليات المعقدة التي تتضمن عدة أنظمة مع ضمان معاملة&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_التدفق_3_الوظائف_المجدولة_وعمليات_المزامنة&quot;&gt;التدفق 3 : الوظائف المجدولة وعمليات المزامنة&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;Failed to generate image: PlantUML preprocessing failed: [From &amp;lt;input&amp;gt; (line 4) ]

@startuml
skinparam backgroundColor #FEFEFE

participant &quot;المجدول
^^^^^
 Syntax Error? (Assumed diagram type: sequence)

@startuml
skinparam backgroundColor #FEFEFE

participant &quot;المجدول
(Spring Boot)&quot; as scheduler
participant &quot;خدمة التقرير&quot; as report
participant &quot;PostgreSQL&quot; as db
participant &quot;واجهة برمجة التطبيقات الخارجية&quot; as api
participant &quot;خدمة البريد الإلكتروني&quot; as email
participant &quot;تخزين Supabase&quot; as storage

== Job Quotidien : 2h00 ==
activate scheduler
scheduler -&amp;gt; report : Déclenche génération rapport

activate report
report -&amp;gt; db : Récupère données\ndes dernières 24h
db -&amp;gt; report : Dataset

report -&amp;gt; report : Calculs &amp;amp; Agrégations
report -&amp;gt; report : Génération PDF

report -&amp;gt; storage : Upload PDF
storage -&amp;gt; report : URL publique

report -&amp;gt; email : Envoie aux admins\navec lien PDF
deactivate report

== Job Hebdomadaire : Dimanche 3h00 ==
scheduler -&amp;gt; report : Synchronisation externe

activate report
report -&amp;gt; api : Fetch données externes
api -&amp;gt; report : Nouvelles données

report -&amp;gt; db : Mise à jour tables
report -&amp;gt; db : Nettoyage données obsolètes
deactivate report

== Job Mensuel : 1er du mois ==
scheduler -&amp;gt; report : Facturation

activate report
report -&amp;gt; db : Liste clients actifs
report -&amp;gt; report : Calcul montants
report -&amp;gt; api : Génération factures (Stripe)
report -&amp;gt; email : Envoi factures
deactivate report

deactivate scheduler

note right of scheduler
  **Impossible avec Supabase seul**
  Edge Functions non adaptées
  pour jobs longs et récurrents
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;ما يجلبه Spring Boot&lt;/strong&gt;: وظائف مجدولة موثوقة مع إدارة الحالة، إعادة محاولة تلقائية، وتنفيذ مضمون.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مصفوفة_القرار&quot;&gt;مصفوفة القرار&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_متى_تستخدم_supabase&quot;&gt;متى تستخدم Supabase؟&lt;/h3&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;supabase-decision.svg&quot; alt=&quot;supabase decision&quot; width=&quot;1030&quot; height=&quot;445&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_متى_تستخدم_spring_boot&quot;&gt;متى تستخدم Spring Boot؟&lt;/h3&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;springboot-decision.svg&quot; alt=&quot;springboot decision&quot; width=&quot;1142&quot; height=&quot;485&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_أمثلة_على_الهندسة_المعمارية_حسب_نوع_المشروع&quot;&gt;أمثلة على الهندسة المعمارية حسب نوع المشروع&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مدونة_بورتفوليو&quot;&gt;مدونة / بورتفوليو&lt;/h3&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;blog-architecture.svg&quot; alt=&quot;blog architecture&quot; width=&quot;1747&quot; height=&quot;5700&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;الحكم&lt;/strong&gt;: 100% Supabase يكفي وأكثر.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_تطبيق_saas&quot;&gt;تطبيق SaaS&lt;/h3&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;saas-architecture.svg&quot; alt=&quot;saas architecture&quot; width=&quot;1752&quot; height=&quot;5748&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;حكم&lt;/strong&gt;: بنية هجينة ضرورية. Supabase للجزء الأساسي، Spring Boot للجزء الحرج (المدفوعات، الفوترة).&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_التجارة_الإلكترونية&quot;&gt;التجارة الإلكترونية&lt;/h3&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;ecommerce-architecture.svg&quot; alt=&quot;ecommerce architecture&quot; width=&quot;1763&quot; height=&quot;5760&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;حكم&lt;/strong&gt;Spring Boot ضروري. Supabase فقط للمصادقة والمكتالوج.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_استراتيجية_الهجرة_التدريجية&quot;&gt;استراتيجية الهجرة التدريجية&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
