&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;مترية&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;قبل&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;بعد&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
