&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_التثبيت_عبر_sdkman_2&quot;&gt;التثبيت عبر SDKMAN!&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_تثبيت_jbake&quot;&gt;&lt;strong&gt;تثبيت JBake&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_التحقق_من_التثبيت_2&quot;&gt;التحقق من التثبيت&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_5_غلاف_gradle_الممارسة_المطلقة_الجيدة&quot;&gt;5. غلاف Gradle: الممارسة المطلقة الجيدة&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_6_دوكير_وبورتينير_للبنّاءات_القابلة_للتكرار_اختياري&quot;&gt;6. دوكير وبورتينير : للبنّاءات القابلة للتكرار (اختياري)&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_تثبيت_docker_engine&quot;&gt;تثبيت Docker Engine&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_تثبيت_docker_عبر_البرنامج_النصي_الرسمي&quot;&gt;&lt;strong&gt;تثبيت Docker عبر البرنامج النصي الرسمي :&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_إدارة_docker_دون_sudo_مُستحسَن&quot;&gt;&lt;strong&gt;إدارة Docker دون &lt;code&gt;sudo&lt;/code&gt; (مُستحسَن) :&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_إدارة_docker_مع_portainer_واجهة_المستخدم_الرسومية&quot;&gt;إدارة Docker مع Portainer (واجهة المستخدم الرسومية)&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_إنشاء_حجم_لبيانات_portainer&quot;&gt;&lt;strong&gt;إنشاء حجم لبيانات Portainer:&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_تشغيل_حاوية_portainer&quot;&gt;&lt;strong&gt;تشغيل حاوية Portainer :&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_الخاتمة&quot;&gt;الخاتمة&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مقدمة&quot;&gt;مقدمة&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;الجمهور المستهدف : مطورين يرغبون في البدء في إنشاء مكونات Gradle.&lt;/div&gt;
&lt;p&gt;لتطوير إضافات Gradle بكفاءة، بيئة تطوير مُهيأة جيدًا ضرورية. سيوفر لك الإعداد الجيد وقتًا، ويقلل من الإحباطات، ويضمن اتساق بنياتك.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;div class=&quot;title&quot;&gt;يركز هذا الدليل على أربعة أعمدة أساسية :&lt;/div&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Le &lt;strong&gt;JDK&lt;/strong&gt;(مجموعة تطوير جافا)، لأن Gradle وJBake يعملان على JVM.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Un &lt;strong&gt;بيئة تطوير متكاملة&lt;/strong&gt;moderne (IntelliJ IDEA) مع دعم جيد لكوتلين وغردل.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Gradle&lt;/strong&gt;نفسه، لبدء المشاريع.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;JBake&lt;/strong&gt;, محرك موقعنا الثابت&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;images/gradle-env.svg&quot; alt=&quot;gradle env&quot; width=&quot;1578&quot; height=&quot;5696&quot;&gt;
&lt;/div&gt;
&lt;div class=&quot;title&quot;&gt;Figure 1. مكونات بيئة التطوير&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_jdk_محرك_gradle&quot;&gt;JDK: محرك Gradle&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Gradle هو تطبيق يعمل على الجهاز الظاهري لجافا (JVM). وبالتالي، فإن تثبيت JDK هو متطلب أساسي مطلق.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ما_الإصدار_الذي_يجب_اختياره&quot;&gt;ما الإصدار الذي يجب اختياره؟&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&amp;lt;/think&amp;gt;ما الإصدار الذي يجب اختياره؟&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;يُوصى باستخدام نسخة LTS (دعم طويل الأمد) من Java. في الوقت الحالي,&lt;strong&gt;JDK 17&lt;/strong&gt; ou &lt;strong&gt;JDK 21&lt;/strong&gt;هي خيارات ممتازة&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_التثبيت_عبر_sdkman_مُوصى_به&quot;&gt;التثبيت عبر SDKMAN! (مُوصى به)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;SDKMAN! هو أداة رائعة لإدارة إصدارات许多 الـSDK، بما في ذلك Java وGradle.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_تثبيت_sdkman&quot;&gt;تثبيت SDKMAN!&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;curl -s &quot;https://get.sdkman.io&quot; | bash source &quot;$HOME/.sdkman/bin/sdkman-init.sh&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_ثبت_نسخة_من_jdk&quot;&gt;ثبت نسخة من JDK&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Pour lister les versions de Java disponibles sdk list java

# Pour installer Java 17 (par exemple, la distribution Temurin)
sdk install java 17.0.8-tem&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_تحقق_من_التثبيت&quot;&gt;تحقق من التثبيت&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;java -version&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;يجب أن ترى النسخة التي قمت لتثبيتها للتو تظهر.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_2_بيئة_التطوير_المتكاملة_intellij_idea&quot;&gt;2. بيئة التطوير المتكاملة : IntelliJ IDEA&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;لتطوير المكونات الإضافية لـ Gradle باستخدام DSL Kotlin,&lt;strong&gt;IntelliJ IDEA&lt;/strong&gt;هو الأداة المفضلة. تكامله مع Gradle و Kotlin لا يضاهى&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;النسخة المجتمعية :&lt;/strong&gt;مجانية وكافية بشكل كبير للبدء&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;النسخة المطلقة :&lt;/strong&gt;مدفوعة، فهي تقدم ميزات متقدمة لتطوير الويب وقواعد البيانات.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;حمل النسخة التي تناسبك من موقع JetBrains : &lt;a href=&quot;https://www.jetbrains.com/idea/download/&quot; class=&quot;bare&quot;&gt;https://www.jetbrains.com/idea/download/&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;سيكتشف IDE تلقائيًا ملفاتك`build.gradle.kts` et &lt;code&gt;settings.gradle.kts&lt;/code&gt;, يقدم لك إكمالًا تلقائيًا قويًا، التنقل في الكود وأدوات تصحيح الأخطاء المدمجة.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_gradle_أداة_البناء&quot;&gt;3. Gradle : أداة البناء&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;على الرغم من أن كل مشروع سيستخدم نسخته الخاصة من Gradle عبر Gradle Wrapper، إلا أنه من المفيد وجود تثبيت عالمي لـ Gradle للمهام مثل تهيئة مشاريع جديدة (&lt;code&gt;gradle init&lt;/code&gt;).&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_التثبيت_عبر_sdkman&quot;&gt;التثبيت عبر SDKMAN!&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;تمامًا مثل JDK، SDKMAN! يُسهّل تثبيت Gradle.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_تثبيت_gradle&quot;&gt;تثبيت Gradle&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sdk install gradle&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_التحقق_من_التثبيت&quot;&gt;&lt;strong&gt;التحقق من التثبيت&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gradle -v&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ستعرض هذا الأمر إصدارات Gradle و Kotlin و Groovy و JDK المستخدمة.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_jbake_مولّد_الموقع_الثابت&quot;&gt;4. JBake : مولّد الموقع الثابت&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;JBake هي الأداة التي سنستخدمها لتحويل ملفات المصدر لدينا (مثل هذا) إلى موقع ويب ثابت. الحصول على تثبيت محلي مفيد لمعاينة التغييرات.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_التثبيت_عبر_sdkman_2&quot;&gt;التثبيت عبر SDKMAN!&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;كما هو الحال مع الأدوات الأخرى، فإن SDKMAN! هي أبسط طريقة.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_تثبيت_jbake&quot;&gt;&lt;strong&gt;تثبيت JBake&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sdk install jbake&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_التحقق_من_التثبيت_2&quot;&gt;التحقق من التثبيت&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;jbake -v&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;سيعرض هذا الأمر إصدار JBake ومعلومات بيئة Java التي يستخدمها.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_5_غلاف_gradle_الممارسة_المطلقة_الجيدة&quot;&gt;5. غلاف Gradle: الممارسة المطلقة الجيدة&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;بمجرد إنشاء مشروعك (الذي سنراه في المقال التالي)، لم تعد بحاجة إلى استخدام الأمر العالمي`gradle`. بدلاً من ذلك، ستستخدم ال&lt;strong&gt;غلاف Gradle&lt;/strong&gt;(&lt;code&gt;./gradlew&lt;/code&gt;), سكريبت مضمّن في مشروعك.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;لماذا؟&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;قابلية التكرار :&lt;/strong&gt;يضمن الغلاف أن كل شخص يعمل على المشروع (بما في ذلك خادم CI/CD الخاص بك) يستخدم بالضبط&lt;strong&gt;نفس نسخة Gradle&lt;/strong&gt;, مما يؤدي إلى إزالة أخطاء البناء بسبب بيئات مختلفة&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;البساطة :&lt;/strong&gt;لا تحتاج إلى تثبيت Gradle يدويًا للمساهمة في مشروع&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;كل ما عليك فعله هو استنساخ المستودع وتشغيله`./gradlew`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;سيبدو أمر نموذجي كالتالي :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Ne pas faire : gradle build
# À faire :
./gradlew build&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_6_دوكير_وبورتينير_للبنّاءات_القابلة_للتكرار_اختياري&quot;&gt;6. دوكير وبورتينير : للبنّاءات القابلة للتكرار (اختياري)&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;على الرغم من عدم كونها ضروريةً بشكل صارم لكتابة إضافة، فإن Docker وPortainer هما أدوات DevOps الحديثة التي تسهّل كثيرًا إنشاء بنى قابلة للتكرار وإدارة بيئتك.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_تثبيت_docker_engine&quot;&gt;تثبيت Docker Engine&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;يسمح لك Docker بحزم تطبيقك والاعتماديات في حاوية.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_تثبيت_docker_عبر_البرنامج_النصي_الرسمي&quot;&gt;&lt;strong&gt;تثبيت Docker عبر البرنامج النصي الرسمي :&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;curl -fsSL https://get.docker.com -o get-docker.sh sudo sh get-docker.sh&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_إدارة_docker_دون_sudo_مُستحسَن&quot;&gt;&lt;strong&gt;إدارة Docker دون &lt;code&gt;sudo&lt;/code&gt; (مُستحسَن) :&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;أضف مستخدمك إلى المجموعة`docker`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sudo usod -aG docker $USER&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock important&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-important&quot; title=&quot;Important&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;

&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;docker run hello-world&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_إدارة_docker_مع_portainer_واجهة_المستخدم_الرسومية&quot;&gt;إدارة Docker مع Portainer (واجهة المستخدم الرسومية)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Portainer هي واجهة ويب خفيفة لإدارة حاويات Docker الخاصة بك.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_إنشاء_حجم_لبيانات_portainer&quot;&gt;&lt;strong&gt;إنشاء حجم لبيانات Portainer:&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;docker volume create portainer_data&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_تشغيل_حاوية_portainer&quot;&gt;&lt;strong&gt;تشغيل حاوية Portainer :&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;docker run -d -p 8000:8000 -p 9443:9443 --name portainer --restart=always -v /var/run/docker.sock:/var/run/docker.sock -v portainer_data:/data portainer/portainer-ce:latest&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;يمكنك الآن الوصول إلى واجهة Portainer على`https://localhost:9443`.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_الخاتمة&quot;&gt;الخاتمة&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;بيئتك الآن جاهزة! لديك JDK، وأفضل بيئة تطوير متكاملة (IDE)، وGradle، وJBake. مع إضافة Docker، أنت أيضًا جاهز لإنشاء بنّاءات حاوية قابلة للتكرار. ستسمح لك هذه القاعدة الصلبة بالتركيز على الجوهر: تطوير إضافات قوية ومفيدة.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;في المقالة القادمة، سنستخدم الأمر`gradle init`لتوليد هيكل مشروع الإضافة الأول لدينا&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_التكامل_مع_poetry&quot;&gt;التكامل مع Poetry&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_تثبيت_poetry&quot;&gt;تثبيت Poetry&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_تهيئة_المشروع&quot;&gt;تهيئة المشروع&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_إضافة_وتثبيت_الاعتماديات&quot;&gt;إضافة وتثبيت الاعتماديات&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_نشر_مع_poetry&quot;&gt;نشر مع Poetry&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_إنشاءات_قابلة_للتكرار_باستخدام_docker&quot;&gt;إنشاءات قابلة للتكرار باستخدام Docker&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_مثال_على_ملف_dockerfile&quot;&gt;مثال على ملف Dockerfile&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_التكامل_في_github_actions&quot;&gt;التكامل في GitHub Actions&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_النشر_الشرطي&quot;&gt;النشر الشرطي&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_أتمتة_التبعيات_مع_renovate_وdependabot&quot;&gt;أتمتة التبعيات مع Renovate وDependabot&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_dependabot&quot;&gt;Dependabot&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_جدّد&quot;&gt;جدّد&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_رسوم_بيانية_plantuml&quot;&gt;رسوم بيانية PlantUML&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_حالة_الاستخدام_cicd_المتقدم&quot;&gt;حالة الاستخدام – CI/CD المتقدم&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_التسلسل_النشر_المشروط&quot;&gt;التسلسل – النشر المشروط&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_الحالات_خط_أنابيب_cicd&quot;&gt;الحالات – خط أنابيب CI/CD&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_النشر_بنية_cicd&quot;&gt;النشر – بنية CI/CD&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_خاتمة&quot;&gt;خاتمة&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;في الجزأين الأولين من هذه السلسلة، لدينا : - أنشأ سير عمل CI/CD وظيفي لتطبيق Python باستخدام GitHub Actions وPyPI. - تم صناعته خط أنابيب مع اختبارات متعددة الإصدارات، ونشر تدريجي عبر Test PyPI، وأدوات للجودة والأمان.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;في هذا الجزء الثالث، سنذهب&lt;strong&gt;ما هو أبعد من مجرد النشر على PyPI&lt;/strong&gt;لبناء سلسلة CI/CD كاملة وقوية واحترافية مع : - &lt;strong&gt;الشعر&lt;/strong&gt;لتغليف حديث وإدارة محسّنة للاعتماديات - &lt;strong&gt;دوكير&lt;/strong&gt;لإنشاء بنى قابلة للتكرار ومتعددة المنصات. - &lt;strong&gt;النشر المشروط&lt;/strong&gt;لإدارة سيناريوهات مثل مرشحات الإصدار - &lt;strong&gt;أدوات الأتمتة&lt;/strong&gt;(Renovate, Dependabot) للحفاظ على مسار التحديث دون أي جهد&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_التكامل_مع_poetry&quot;&gt;التكامل مع Poetry&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Poetry يحل محل أدوات التغليف القديمة (setup.py, requirements.txt) من خلال تركيز إدارة الاعتمادات والبناء في`pyproject.toml`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_تثبيت_poetry&quot;&gt;تثبيت Poetry&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;shell&quot;&gt;# Installer Poetry
curl -sSL https://install.python-poetry.org | python3 -
# Vérifier la version
poetry --version&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_تهيئة_المشروع&quot;&gt;تهيئة المشروع&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;shell&quot;&gt;# Initialiser un nouveau projet avec Poetry
poetry init
# Suivre l&#39;assistant pour renseigner : nom, version, description, licence, dépendances.&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;هذا يولد ملفاً`pyproject.toml`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;toml&quot;&gt;[tool.poetry]
name = &quot;playlist-downloader&quot;
version = &quot;0.1.0&quot;
description = &quot;CLI tool for managing YouTube playlists&quot;
authors = [&quot;Christophe Hérolivier &amp;lt;cheroliv@example.com&amp;gt;&quot;]

[tool.poetry.dependencies]
python = &quot;&amp;gt;=3.8&quot;
typer = &quot;^0.9.0&quot;
yt-dlp = &quot;^2023.7.6&quot;
google-api-python-client = &quot;^2.0.0&quot;
google-auth-oauthlib = &quot;^1.0.0&quot;

[tool.poetry.group.dev.dependencies]
pytest = &quot;^7.0&quot;
mypy = &quot;^1.0&quot;
bandit = &quot;^1.7&quot;
safety = &quot;^2.3&quot;
black = &quot;^23.0&quot;
ruff = &quot;^0.1&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_إضافة_وتثبيت_الاعتماديات&quot;&gt;إضافة وتثبيت الاعتماديات&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;shell&quot;&gt;poetry add typer yt-dlp google-api-python-client google-auth-oauthlib
poetry add --group dev pytest mypy black bandit safety ruff&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_نشر_مع_poetry&quot;&gt;نشر مع Poetry&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Poetry يتعامل بشكل أصلي مع النشر :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;shell&quot;&gt;# Publication sur Test PyPI
poetry publish --build --repository test-pypi

# Publication sur PyPI
poetry publish --build&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;يستخدم هذا الأمر تلقائيًا المعلومات الموجودة في`pyproject.toml`.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_إنشاءات_قابلة_للتكرار_باستخدام_docker&quot;&gt;إنشاءات قابلة للتكرار باستخدام Docker&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ضمانًا لتنفيذات متطابقة في التطوير، وCI/CD، والإنتاج، يتكامل Docker بشكل مثالي مع Poetry.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مثال_على_ملف_dockerfile&quot;&gt;مثال على ملف Dockerfile&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;dockerfile&quot;&gt;FROM python:3.11-slim

WORKDIR /app
COPY pyproject.toml poetry.lock ./
RUN pip install poetry
RUN poetry install --no-root --only main

COPY . .

CMD [&quot;poetry&quot;, &quot;run&quot;, &quot;python&quot;, &quot;cli.py&quot;]&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;هذا يضمن: - بيئة Python ثابتة. - تبعيات مغلقة عبر`poetry.lock`. - صورة قابلة للتنفيذ على أي نظام يدعم Docker.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_التكامل_في_github_actions&quot;&gt;التكامل في GitHub Actions&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;yaml&quot;&gt;name: Docker Build

on:
  push:
    branches: [main]

jobs:
  build-docker:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - name: Build Docker image
        run: docker build -t ghcr.io/${{ github.repository }}:latest .
      - name: Push Docker image
        run: docker push ghcr.io/${{ github.repository }}:latest&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_النشر_الشرطي&quot;&gt;النشر الشرطي&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;في خط أنابيب احترافي، يجب أن تكون قادرًا على النشر فقط في بعض الحالات: - مرشحات الإصدار إلى اختبار PyPI. - النسخ المستقرة إلى PyPI. - إنشاءات Docker التي يتم تشغيلها فقط لـ`main`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;yaml&quot;&gt;- name: Publish to Test PyPI
  if: contains(github.ref, &#39;-rc&#39;)
  run: poetry publish --build --repository test-pypi

- name: Publish to PyPI
  if: startsWith(github.ref, &#39;refs/tags/v&#39;)
  run: poetry publish --build&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;هذا النهج يتجنب النشر العرضي.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_أتمتة_التبعيات_مع_renovate_وdependabot&quot;&gt;أتمتة التبعيات مع Renovate وDependabot&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;لتجنب أن تصبح تبعياتك قديمة، ادمج أدوات التحديث التلقائي.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_dependabot&quot;&gt;Dependabot&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;yaml&quot;&gt;version: 2
updates:
  - package-ecosystem: &quot;pip&quot;
    directory: &quot;/&quot;
    schedule:
      interval: &quot;weekly&quot;
  - package-ecosystem: &quot;github-actions&quot;
    directory: &quot;/&quot;
    schedule:
      interval: &quot;weekly&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dependabot يفتح طلبات سحب (PR) كل أسبوع لتحديث تبعيات Python و GitHub Actions.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_جدّد&quot;&gt;جدّد&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;json&quot;&gt;{
  &quot;extends&quot;: [&quot;config:base&quot;],
  &quot;packageRules&quot;: [
    {
      &quot;matchManagers&quot;: [&quot;pip&quot;],
      &quot;groupName&quot;: &quot;python-dependencies&quot;,
      &quot;schedule&quot;: [&quot;before 6am on monday&quot;]
    }
  ]
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Renovate يسمح بالتحكم الأدق: تجميع التبعيات، التخطيط، والقواعد المتقدمة.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_رسوم_بيانية_plantuml&quot;&gt;رسوم بيانية PlantUML&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_حالة_الاستخدام_cicd_المتقدم&quot;&gt;حالة الاستخدام – CI/CD المتقدم&lt;/h3&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;images/usecase-cicd.svg&quot; alt=&quot;usecase cicd&quot; width=&quot;789&quot; height=&quot;317&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_التسلسل_النشر_المشروط&quot;&gt;التسلسل – النشر المشروط&lt;/h3&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;images/sequence-cicd.svg&quot; alt=&quot;sequence cicd&quot; width=&quot;275&quot; height=&quot;571&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_الحالات_خط_أنابيب_cicd&quot;&gt;الحالات – خط أنابيب CI/CD&lt;/h3&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;images/states-cicd.svg&quot; alt=&quot;states cicd&quot; width=&quot;284&quot; height=&quot;608&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_النشر_بنية_cicd&quot;&gt;النشر – بنية CI/CD&lt;/h3&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;images/deployment-cicd.svg&quot; alt=&quot;deployment cicd&quot; width=&quot;1600&quot; height=&quot;5616&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_خاتمة&quot;&gt;خاتمة&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;في هذا الجزء الثالث، رأينا كيف : - تطوير تغليف Python باستخدام Poetry. ضمان بناءات قابلة للتكرار عبر Docker. إعداد نشر مشروط أتمتة تحديث التبعيات.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;أنت الآن تمتلك خط أنابيب CI/CD&lt;strong&gt;كامل، صناعي وآمن&lt;/strong&gt;, مستعد للتطور مع مشاريعك.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_مقدمة&quot;&gt;مقدمة&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_هندسة_مسار_cicd&quot;&gt;هندسة مسار CI/CD&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_هيكل_المشروع&quot;&gt;هيكل المشروع&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_إعداد_الحزمة_باستخدام_pyproject_toml&quot;&gt;إعداد الحزمة باستخدام pyproject.toml&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_سير_عمل_cicd_اختبارات_وجودة&quot;&gt;سير عمل CI/CD - اختبارات وجودة&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_سير_عمل_الإصدار_والنشر&quot;&gt;سير عمل الإصدار والنشر&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مخططات_المعمارية&quot;&gt;مخططات المعمارية&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_مخطط_التسلسل_عملية_الإصدار&quot;&gt;مخطط التسلسل - عملية الإصدار&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مخطط_الحالة_دورة_حياة_الحزمة&quot;&gt;مخطط الحالة - دورة حياة الحزمة&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مخطط_النشر_البنية_التحتية_لـ_cicd&quot;&gt;مخطط النشر - البنية التحتية لـ CI/CD&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_الكائنات_والنماذج_في_خط_الأنابيب&quot;&gt;الكائنات والنماذج في خط الأنابيب&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_مخطط_الفئات_نماذج_cicd&quot;&gt;مخطط الفئات - نماذج CI/CD&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_تكوين_الأسرار&quot;&gt;تكوين الأسرار&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_أسرار_github_actions&quot;&gt;أسرار GitHub Actions&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_إنشاء_رموز_pypi&quot;&gt;إنشاء رموز PyPI&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_سكريبتات_التطوير_المحلي&quot;&gt;سكريبتات التطوير المحلي&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_makefile&quot;&gt;Makefile&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_سكريبت_الإصدار&quot;&gt;سكريبت الإصدار&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_الممارسات_الجيدة_والتوصيات&quot;&gt;الممارسات الجيدة والتوصيات&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_الإصدار_الدلالي&quot;&gt;الإصدار الدلالي&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_استراتيجية_التفرع&quot;&gt;استراتيجية التفرع&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_اختبارات_وتغطية&quot;&gt;اختبارات وتغطية&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_أمان&quot;&gt;أمان&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_المراقبة_والملاحظة&quot;&gt;المراقبة والملاحظة&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_مقاييس_خط_الأنابيب&quot;&gt;مقاييس خط الأنابيب&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_الإشعارات&quot;&gt;الإشعارات&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_الاستنتاج&quot;&gt;الاستنتاج&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مصادر_مكملة&quot;&gt;مصادر مكملة&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مقدمة&quot;&gt;مقدمة&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;الهدف : تحويل خط أنابيب بسيط إلى خط أنابيب صناعي قوي، يلتزم بالمعايير الحديثة للتغليف والهندسة البرمجية.&lt;/div&gt;
&lt;p&gt;في الجزء الأول من هذه السلسلة، أنشأنا مسار CI/CD بسيطًا لكن فعالًا لأتمتة الاختبارات ونشر حزمة Python على PyPI.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;الآن هو الوقت لتطوير هذا الخط أنبوبًا بشكل احترافي. في هذا الجزء الثاني، سن:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;الانتقال إلى معيار pyproject.toml الحديث,&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;إضافة أدوات الجودة والأمان (Black, Mypy, Bandit, Safety)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;إعداد اختبارات متعددة الإصدارات،&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;دمج نشر تدريجي عبر Test PyPI,&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;أتمتة إدارة الإصدارات وتحسين مراقبة خط الأنابيب.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;استعد للانتقال من خط أنابيب وظيفي إلى بنية تحتية احترافية لـ CI/CD.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;نشر تطبيق Python على PyPI يتطلب عملية CI/CD قوية تُ automate الاختبارات، والبناء، ونشر الحزم. هذا المقال يوضح إعداد مسار عمل كامل باستخدام GitHub Actions لتطبيق سطر أوامر بلغة Python، اعتمادًا على أفضل ممارسات بيئة Python الحديثة.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_هندسة_مسار_cicd&quot;&gt;هندسة مسار CI/CD&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;خط الأنابيب الذي سنقوم بإنشائه يتبع نهجًا متعدد المراحل :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;images/diag-plantuml-md5-eb0e55004ec6a9e73143f8dbeedbd984.png&quot; alt=&quot;Diagram&quot; width=&quot;846&quot; height=&quot;604&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_هيكل_المشروع&quot;&gt;هيكل المشروع&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;يجب أن يلتزم تطبيق CLI بايثون جاهز للتوزيع بهيكل موحد:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;text&quot;&gt;playlist-downloader/
├── .github/
│   └── workflows/
│       ├── ci.yml
│       ├── release.yml
│       └── security.yml
├── src/
│   └── playlist_downloader/
│       ├── __init__.py
│       ├── cli.py
│       ├── core/
│       └── adapters/
├── tests/
│   ├── unit/
│   ├── integration/
│   └── conftest.py
├── docs/
├── pyproject.toml
├── requirements.txt
├── requirements-dev.txt
├── MANIFEST.in
├── README.md
├── LICENSE
└── CHANGELOG.md&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_إعداد_الحزمة_باستخدام_pyproject_toml&quot;&gt;إعداد الحزمة باستخدام pyproject.toml&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;الملف`pyproject.toml`هو المعيار الحديث لتكوين حزم بايثون :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;toml&quot;&gt;[build-system]
requires = [&quot;setuptools&amp;gt;=45&quot;, &quot;wheel&quot;, &quot;setuptools_scm&amp;gt;=6.2&quot;]
build-backend = &quot;setuptools.build_meta&quot;

[project]
name = &quot;playlist-downloader&quot;
authors = [
    {name = &quot;Christophe Hérolivier&quot;, email = &quot;cheroliv@example.com&quot;},
]
description = &quot;CLI tool for YouTube playlist management&quot;
readme = &quot;README.md&quot;
requires-python = &quot;&amp;gt;=3.8&quot;
keywords = [&quot;youtube&quot;, &quot;playlist&quot;, &quot;cli&quot;, &quot;downloader&quot;]
license = {text = &quot;MIT&quot;}
classifiers = [
    &quot;Development Status :: 4 - Beta&quot;,
    &quot;Environment :: Console&quot;,
    &quot;Intended Audience :: End Users/Desktop&quot;,
    &quot;License :: OSI Approved :: MIT License&quot;,
    &quot;Operating System :: OS Independent&quot;,
    &quot;Programming Language :: Python :: 3&quot;,
    &quot;Programming Language :: Python :: 3.8&quot;,
    &quot;Programming Language :: Python :: 3.9&quot;,
    &quot;Programming Language :: Python :: 3.10&quot;,
    &quot;Programming Language :: Python :: 3.11&quot;,
    &quot;Topic :: Multimedia :: Sound/Audio&quot;,
    &quot;Topic :: Utilities&quot;,
]
dependencies = [
    &quot;typer&amp;gt;=0.9.0&quot;,
    &quot;yt-dlp&amp;gt;=2023.7.6&quot;,
    &quot;google-api-python-client&amp;gt;=2.0.0&quot;,
    &quot;google-auth-oauthlib&amp;gt;=1.0.0&quot;,
    &quot;pyyaml&amp;gt;=6.0&quot;,
    &quot;rich&amp;gt;=13.0.0&quot;,
]
dynamic = [&quot;version&quot;]

[project.optional-dependencies]
dev = [
    &quot;pytest&amp;gt;=7.0.0&quot;,
    &quot;pytest-cov&amp;gt;=4.0.0&quot;,
    &quot;pytest-mock&amp;gt;=3.10.0&quot;,
    &quot;black&amp;gt;=23.0.0&quot;,
    &quot;flake8&amp;gt;=6.0.0&quot;,
    &quot;mypy&amp;gt;=1.0.0&quot;,
    &quot;pre-commit&amp;gt;=3.0.0&quot;,
    &quot;tox&amp;gt;=4.0.0&quot;,
]
test = [
    &quot;pytest&amp;gt;=7.0.0&quot;,
    &quot;pytest-cov&amp;gt;=4.0.0&quot;,
    &quot;pytest-mock&amp;gt;=3.10.0&quot;,
]

[project.urls]
Homepage = &quot;https://github.com/cheroliv/playlist-downloader&quot;
Documentation = &quot;https://github.com/cheroliv/playlist-downloader#readme&quot;
Repository = &quot;https://github.com/cheroliv/playlist-downloader.git&quot;
&quot;Bug Tracker&quot; = &quot;https://github.com/cheroliv/playlist-downloader/issues&quot;

[project.scripts]
playlist-downloader = &quot;playlist_downloader.cli:main&quot;

[tool.setuptools_scm]
write_to = &quot;src/playlist_downloader/_version.py&quot;

[tool.setuptools.packages.find]
where = [&quot;src&quot;]

[tool.pytest.ini_options]
testpaths = [&quot;tests&quot;]
python_files = [&quot;test_*.py&quot;]
python_classes = [&quot;Test*&quot;]
python_functions = [&quot;test_*&quot;]
addopts = [
    &quot;--cov=src/playlist_downloader&quot;,
    &quot;--cov-report=html&quot;,
    &quot;--cov-report=term-missing&quot;,
    &quot;--cov-fail-under=85&quot;,
]

[tool.black]
line-length = 88
target-version = [&#39;py38&#39;]
include = &#39;\.pyi?$&#39;
extend-exclude = &#39;&#39;&#39;
/(
  \.eggs
  | \.git
  | \.hg
  | \.mypy_cache
  | \.tox
  | \.venv
  | _build
  | buck-out
  | build
  | dist
)/
&#39;&#39;&#39;

[tool.mypy]
python_version = &quot;3.8&quot;
warn_return_any = true
warn_unused_configs = true
disallow_untyped_defs = true
disallow_incomplete_defs = true
check_untyped_defs = true
disallow_untyped_decorators = true
no_implicit_optional = true
warn_redundant_casts = true
warn_unused_ignores = true
warn_no_return = true
warn_unreachable = true
strict_equality = true

[[tool.mypy.overrides]]
module = [
    &quot;yt_dlp.*&quot;,
    &quot;googleapiclient.*&quot;,
    &quot;google_auth_oauthlib.*&quot;,
]
ignore_missing_imports = true&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_سير_عمل_cicd_اختبارات_وجودة&quot;&gt;سير عمل CI/CD - اختبارات وجودة&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;سلسلة العمل الرئيسية (&lt;code&gt;ci.yml&lt;/code&gt;) ينفذ الاختبارات على عدة إصدارات من بايثون :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;yaml&quot;&gt;name: CI

on:
  push:
    branches: [ main, develop ]
  pull_request:
    branches: [ main ]

jobs:
  test:
    runs-on: ubuntu-latest
    strategy:
      matrix:
        python-version: [&quot;3.8&quot;, &quot;3.9&quot;, &quot;3.10&quot;, &quot;3.11&quot;]

    steps:
    - uses: actions/checkout@v4
      with:
        fetch-depth: 0

    - name: Set up Python ${{ matrix.python-version }}
      uses: actions/setup-python@v4
      with:
        python-version: ${{ matrix.python-version }}

    - name: Cache dependencies
      uses: actions/cache@v3
      with:
        path: |
          ~/.cache/pip
          ~/.cache/pre-commit
        key: ${{ runner.os }}-pip-${{ hashFiles(&#39;**/requirements*.txt&#39;) }}
        restore-keys: |
          ${{ runner.os }}-pip-

    - name: Install dependencies
      run: |
        python -m pip install --upgrade pip
        pip install -e &quot;.[dev]&quot;

    - name: Lint with flake8
      run: |
        flake8 src tests --count --select=E9,F63,F7,F82 --show-source --statistics
        flake8 src tests --count --exit-zero --max-complexity=10 --max-line-length=88 --statistics

    - name: Check code formatting with Black
      run: black --check src tests

    - name: Type checking with mypy
      run: mypy src

    - name: Run tests with pytest
      run: |
        pytest tests/ -v --cov=src/playlist_downloader \
          --cov-report=xml --cov-report=term-missing

    - name: Upload coverage to Codecov
      uses: codecov/codecov-action@v3
      if: matrix.python-version == &#39;3.11&#39;
      with:
        file: ./coverage.xml
        flags: unittests
        name: codecov-umbrella

  security:
    runs-on: ubuntu-latest
    steps:
    - uses: actions/checkout@v4

    - name: Set up Python
      uses: actions/setup-python@v4
      with:
        python-version: &quot;3.11&quot;

    - name: Install dependencies
      run: |
        python -m pip install --upgrade pip
        pip install bandit[toml] safety

    - name: Run security checks with bandit
      run: bandit -r src/ -f json -o bandit-report.json

    - name: Check dependencies with safety
      run: safety check --json --output safety-report.json

    - name: Upload security reports
      uses: actions/upload-artifact@v3
      if: always()
      with:
        name: security-reports
        path: |
          bandit-report.json
          safety-report.json

  build:
    needs: [test, security]
    runs-on: ubuntu-latest
    steps:
    - uses: actions/checkout@v4
      with:
        fetch-depth: 0

    - name: Set up Python
      uses: actions/setup-python@v4
      with:
        python-version: &quot;3.11&quot;

    - name: Install build dependencies
      run: |
        python -m pip install --upgrade pip
        pip install build twine

    - name: Build package
      run: python -m build

    - name: Check package with twine
      run: twine check dist/*

    - name: Upload build artifacts
      uses: actions/upload-artifact@v3
      with:
        name: dist
        path: dist/&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_سير_عمل_الإصدار_والنشر&quot;&gt;سير عمل الإصدار والنشر&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;سير عمل الإطلاق (&lt;code&gt;release.yml&lt;/code&gt;) يدير النشر التلقائي على PyPI :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;pygments highlight&quot;&gt;&lt;code data-lang=&quot;yaml&quot;&gt;name: Release

on:
  push:
    tags:
      - &#39;v*.*.*&#39;
  workflow_dispatch:
    inputs:
      environment:
        description: &#39;Deployment environment&#39;
        required: true
        default: &#39;test&#39;
        type: choice
        options:
        - test
        - production

env:
  PYTHON_VERSION: &quot;3.11&quot;

jobs:
  release:
    runs-on: ubuntu-latest
    environment:
      name: ${{ github.event.inputs.environment || (startsWith(github.ref, &#39;refs/tags/&#39;) &amp;amp;&amp;amp; &#39;production&#39; || &#39;test&#39;) }}

    steps:
    - uses: actions/checkout@v4
      with:
        fetch-depth: 0

    - name: Set up Python
      uses: actions/setup-python@v4
      with:
        python-version: ${{ env.PYTHON_VERSION }}

    - name: Install dependencies
      run: |
        python -m pip install --upgrade pip
        pip install build twine

    - name: Build package
      run: python -m build

    - name: Check package
      run: twine check dist/*

    - name: Publish to Test PyPI
      if: github.event.inputs.environment == &#39;test&#39; || (startsWith(github.ref, &#39;refs/tags/&#39;) &amp;amp;&amp;amp; contains(github.ref, &#39;rc&#39;))
      env:
        TWINE_USERNAME: __token__
        TWINE_PASSWORD: ${{ secrets.TEST_PYPI_API_TOKEN }}
      run: |
        twine upload --repository testpypi dist/*

    - name: Publish to PyPI
      if: github.event.inputs.environment == &#39;production&#39; || (startsWith(github.ref, &#39;refs/tags/&#39;) &amp;amp;&amp;amp; !contains(github.ref, &#39;rc&#39;))
      env:
        TWINE_USERNAME: __token__
        TWINE_PASSWORD: ${{ secrets.PYPI_API_TOKEN }}
      run: |
        twine upload dist/*

    - name: Create GitHub Release
      if: startsWith(github.ref, &#39;refs/tags/&#39;)
      uses: actions/create-release@v1
      env:
        GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
      with:
        tag_name: ${{ github.ref }}
        release_name: Release ${{ github.ref }}
        draft: false
        prerelease: ${{ contains(github.ref, &#39;rc&#39;) }}

  post-release:
    needs: release
    runs-on: ubuntu-latest
    if: startsWith(github.ref, &#39;refs/tags/&#39;)

    steps:
    - uses: actions/checkout@v4

    - name: Set up Python
      uses: actions/setup-python@v4
      with:
        python-version: ${{ env.PYTHON_VERSION }}

    - name: Test installation from PyPI
      run: |
        sleep 60  # Attendre la propagation sur PyPI
        pip install playlist-downloader
        playlist-downloader --version

    - name: Update documentation
      run: |
        # Script pour mettre à jour la documentation
        echo &quot;Documentation updated for version ${GITHUB_REF#refs/tags/}&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
