&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_أساسية_وظيفية&quot;&gt;أساسية وظيفية&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_النهج_التصريحي_x_الأمر&quot;&gt;النهج التصريحي X الأمر&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;package functional

import kotlin.test.Test
import kotlin.test.assertEquals

class DeclarativeTests {
    val input = listOf(
        &quot;123&quot;, &quot;abc&quot;, &quot;1ds&quot;, &quot;987&quot;, &quot;abdf&quot;, &quot;1d3&quot;, &quot;de1&quot;, &quot;88&quot;, &quot;101&quot;
    )

    fun imperativeSum(list: List&amp;lt;String&amp;gt;): Int {
        var sum = 0
        for (item in list) {
            try {
                sum += item.toInt()
            } catch (_: NumberFormatException) {
            }
        }
        return sum
    }

    @Test
    fun `test imperative approach`() {
        imperativeSum(input).run {
            println(&quot;Sum $this&quot;)
            assertEquals(1299, this)
        }
    }

    fun isValidNumber(s: String) = try {
        s.toInt()
        true
    } catch (_: NumberFormatException) {
        false
    }

    fun declarativeSum(list: List&amp;lt;String&amp;gt;) = list
        .filter(::isValidNumber)
        .map(String::toInt)
        .sum()

    @Test
    fun `test declarative approach`() {
        assertEquals(1299, declarativeSum(input).apply {
            println(&quot;Sum $this&quot;)
        })
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_تمرين_1_1&quot;&gt;تمرين 1.1&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;قم بتنفيذ الدالة sumInRange، التي تجمع القيم في&lt;br&gt;
قائمة&amp;lt;String&amp;gt; في نطاق معين. التوقيع هو :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;fun sumInRange(input: List&amp;lt;String&amp;gt;, range: IntRange): Int&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;@Test
fun `Exercise 1_1`() {
    assertEquals(4, sumInRange(
        listOf(&quot;1&quot;, &quot;10&quot;, &quot;a&quot;, &quot;7&quot;, &quot;ad2&quot;, &quot;3&quot;),
            1..5
        ).apply { println(&quot;sumInRange 1..5: $this&quot;) }
    )
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;جربه وتحقق من إجابتك معhttps://github.com/cheroliv/cheroliv.com/blob/master/codes/src/test/kotlin/functional/DeclarativeTests.kt[حل, windows=&quot;_blank].&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_الوظائف_ذات_الترتيب_الأعلى&quot;&gt;الوظائف ذات الترتيب الأعلى&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;package functional

import java.io.ByteArrayOutputStream
import java.io.PrintStream
import java.lang.System.*
import java.lang.Thread.sleep
import kotlin.math.sign
import kotlin.test.Test
import kotlin.test.assertEquals

class BasicsHOFTests {
    val ONE_SECOND = 1000L

    @Test
    fun `high order function`() {
        //capture de la sortie standard
        val standardOut: PrintStream? = out
        val outputStreamCaptor = ByteArrayOutputStream()
        setOut(PrintStream(outputStreamCaptor))

        3.times { println(&quot;Hello&quot;) }
        assertEquals(
            buildString {
                repeat(3) { append(&quot;Hello\n&quot;) }
                deleteAt(length - 1)
            }, outputStreamCaptor
                .toString()
                .trim()
        )

        //libération de la sortie standard
        setOut(standardOut)
    }

    fun Int.times1(fn: () -&amp;gt; Unit) {
        for (i in 1..this) {
            fn()
        }
    }

    fun Int.times2(fn: () -&amp;gt; Unit) {
        for (i in 1..this) fn()
    }

    fun Int.times3(fn: () -&amp;gt; Unit) =
        (1..this).forEach { fn() }


    fun Int.times4(fn: () -&amp;gt; Unit) =
        repeat((1..this).count()) { fn() }

    fun Int.times(fn: () -&amp;gt; Unit) =
        (1..this).forEach { _ -&amp;gt; fn() }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_تمرين_1_2&quot;&gt;تمرين 1.2&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;نفّذ chrono، الذي يقبل دالة من النوع`() &amp;#8594;`&lt;br&gt;
الوحدة في المدخل وتعيد الوقت المستغرق في تنفيذها. التوقيع هو :&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;fun chrono(fn : () -&amp;gt; Unité) : Long&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;@Test
fun `Exercise 1_2`() {
    val waitOneSec = { sleep(ONE_SECOND) }
    chrono(waitOneSec).apply {
        println(&quot;chrono: $this&quot;)
        assertEquals(1, sign)
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;جربه وتحقق من إجابتك معhttps://github.com/cheroliv/cheroliv.com/blob/master/codes/src/test/kotlin/functional/BasicsHOFTests.kt[الحل, windows=&quot;_blank].&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_التأليف&quot;&gt;التأليف&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;package functional

import kotlin.test.Test
import kotlin.test.assertEquals


fun double(x: Int): Int = 2 * x
fun square(x: Int): Int = x * x
fun squareAndDouble1(x: Int) = double(square(x))

infix fun &amp;lt;A, B, C&amp;gt; ((A) -&amp;gt; B).compose(g: (B) -&amp;gt; C)
        : (A) -&amp;gt; C = { a -&amp;gt; g(this(a)) }

class CompositionTests {
    @Test
    fun composition_impure() {
        assertEquals(200, double(square(10)))
        assertEquals(200, squareAndDouble1(10))
    }

    @Test
    fun composition_pure() {
        val squareAndDouble = ::square compose ::double
        assertEquals(200, squareAndDouble(10))
    }

}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_الوظائف_النقية_وقابلية_الاختبار&quot;&gt;الوظائف النقية وقابلية الاختبار&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;package functional

import java.io.ByteArrayOutputStream
import java.io.PrintStream
import java.lang.System.out
import java.lang.System.setOut
import kotlin.test.Test
import kotlin.test.assertEquals


var count = 0

//impure car une variable global subit un effet de bord
fun impure(value: Int): Int {
    count++
    return value + count
}

//impure car utilisation de la sortie standard qui fait muter le system
fun addOneAndLog(x: Int): Int {
    val result = x + 1
    println(&quot;New Value is $result&quot;)
    return result
}

//pure
fun addOne(x: Int) = (x + 1).run {
    Pair(this, &quot;New Value is $this&quot;)
}

class PureTests {
    @Test
    fun `impure fonction`() {
        assertEquals(3, impure(2))

        val standardOut = out
        val outputStreamCaptor = ByteArrayOutputStream()
        setOut(PrintStream(outputStreamCaptor))

        addOneAndLog(3)

        assertEquals(
            &quot;New Value is 4&quot;,
            outputStreamCaptor
                .toString()
                .trim()
        )
        setOut(standardOut)
    }

    @Test
    fun `pure fonction`() {
        addOne(3).run {
            assertEquals(4, first)
            assertEquals(&quot;New Value is 4&quot;, second)
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_معالجة_الاستثناءات&quot;&gt;معالجة الاستثناءات&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;package functional

import org.junit.jupiter.api.assertThrows
import kotlin.Result.Companion.failure
import kotlin.Result.Companion.success
import kotlin.test.Test
import kotlin.test.assertEquals

//NumberFormatException est un effet de bord qui rend la fonction impure
fun strToInt(str: String) = str.toInt()

//pure
fun strToIntOrNull(str: String) = try {
    str.toInt()
} catch (nfe: NumberFormatException) {
    null
}

//pure avec gestion de l&#39;exception plus élégante
fun strToIntResult(str: String): Result&amp;lt;Int&amp;gt; =
    try {
        success(str.toInt())
    } catch (nfe: NumberFormatException) {
        failure(nfe)
    }

class ExceptionHandlingTests {
    @Test
    fun impure() {
        assertThrows&amp;lt;NumberFormatException&amp;gt; { strToInt(&quot;foo&quot;) }
        assertEquals(1, strToInt(&quot;1&quot;))
    }

    @Test
    fun pure() {
        assertEquals(null, strToIntOrNull(&quot;foo&quot;))
        assertEquals(1, strToIntOrNull(&quot;1&quot;))
    }

    @Test
    fun `pure avec result`() {
        assertEquals(1, strToIntResult(&quot;1&quot;).getOrNull())
        assertEquals(
            &quot;For input string: \&quot;foo\&quot;&quot;,
            strToIntResult(&quot;foo&quot;)
                .exceptionOrNull()
                ?.message
        )
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_نقاط_رئيسية&quot;&gt;نقاط رئيسية&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;في حين أن البرمجة الموجهة بالكائنات تعني البرمجة مع الكائنات،&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;البرمجة الوظيفية تعني البرمجة باستخدام الدوال. تقوم بتقسيم مشكلة إلى عدة مشكلات فرعية، وتقوم بنمذجتها باستخدام الوظائف&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;الوظائف ذات الترتيب الأعلى تقبل وظائف أخرى كمدخل أو تُرجع وظائف أخرى&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;تعمل كقيم إرجاع نظرية الفئات هي نظرية التركيب، وأنت تستخدمها لفهم كيف يمكنك تركيب وظائفك في برنامج عمل. قيمة إخراج الدالة النقية تعتمد فقط على معلمات الإدخال الخاصة بها، وهي ليس له آثار جانبية&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;التأثير الجانبي هو شيء تقوم به الوظيفة إلى العالم الخارجي. هذا&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;قد يكون سجلًا في المخرج القياسي أو تعديل قيمة متغير عام. البرمجة الوظيفية تعمل للوظائف النقية، لكنها توفر أيضًا أدوات لتحويل الوظائف غير النقية إلى وظائف نقية. يمكنك تحويل وظيفة غير نقية إلى نقية بنقل الآثار لجعلها جزء من قيمة الإرجاع.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;البرمجة الوظيفية هي مسألة تركيب.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;إدارة الأخطاء هي حالة نموذجية للآثار الجانبية، وكوتولين تزودك بالأدوات لإدارتها وظيفياً&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_تعميق_java8_تعبيرات_lambda_والواجهات_الوظيفية&quot;&gt;تعميق java8: تعبيرات lambda والواجهات الوظيفية&lt;/h3&gt;
&lt;div class=&quot;videoblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;iframe src=&quot;https://www.youtube.com/embed/20waNRw6wMA?rel=0&amp;amp;list=PLzzeuFUy_Cng0wZhqbnkvWAW0d2fdVfyQ&quot; frameborder=&quot;0&quot; allowfullscreen&gt;&lt;/iframe&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_نظرية_الفئات&quot;&gt;نظرية الفئات&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;النظرية الرياضية للفئات:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;videoblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;iframe src=&quot;https://www.youtube.com/embed/LVHoROSF3KA?rel=0&quot; frameborder=&quot;0&quot; allowfullscreen&gt;&lt;/iframe&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_أساسيات_الدوال&quot;&gt;أساسيات الدوال&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_تمرين_2_1&quot;&gt;تمرين 2.1&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;هل يمكنك كتابة مثال على دالة تُطابق قيمًا مميزة&lt;br&gt;
حيث أن المجال يأخذ قيمًا غير متميزة في المجال، مثل f(b) و f(c) في الشكل أدناه؟&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;جربه، ثم تحقق من مشروع التحدي للحصول على حل لترى كيف فعلت ذلك&lt;br&gt;
ستجد نصائح وشرحًا باتباع الرابط إلى ال &lt;a href=&quot;https://github.com/cheroliv/cheroliv.com/blob/master/codes/src/test/kotlin/functional/BasicsHOFTests.kt&quot;&gt;الحل&lt;/a&gt;.&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_تمرين_2_2&quot;&gt;تمرين 2.2&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;هل يمكنك كتابة الدالة العكسية للضعف؟&lt;br&gt;
ما هما المجال والمدى للدالة العكسرية؟&lt;br&gt;
تحقق من مشروع التحدي والملحق B للحصول على الحل.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;fun chrono(fn : () -&amp;gt; Unité) : Long&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;@Test
fun `Exercise 1_2`() {
    val waitOneSec = { sleep(ONE_SECOND) }
    chrono(waitOneSec).apply {
        println(&quot;chrono: $this&quot;)
        assertEquals(1, sign)
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;جربه وتحقق من إجابتك معhttps://github.com/cheroliv/cheroliv.com/blob/master/codes/src/test/kotlin/functional/BasicsHOFTests.kt[حل, نوافذ=&quot;_blank].&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_أدوات&quot;&gt;أدوات&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;div class=&quot;title&quot;&gt;&lt;strong&gt;الرسوم التوضيحية&lt;/strong&gt;&lt;/div&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;a href=&quot;https://undraw.co/&quot;&gt;undraw.co&lt;/a&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;رسومات مفتوحة المصدر لجميع الأفكار التي يمكنك تخيلها وإنشاؤها.&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;a href=&quot;https://absurd.design/&quot;&gt;absurd.design&lt;/a&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;رسوم توضيحية سخيفة لها معنى&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;a href=&quot;https://drawkit.com/&quot;&gt;drawkit.com&lt;/a&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;رسوم توضيحية جميلة مجانية. تحديثات أسبوعية.&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;a href=&quot;https://icons8.com/&quot;&gt;icons8.com&lt;/a&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;أيكونات، رسوم توضيحية، صور، موسيقى، وأدوات تصميم.&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;a href=&quot;https://blush.design/&quot;&gt;blush.design&lt;/a&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;أيقونات, رسومات, صور, موسيقى و أدوات التصميم&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;a href=&quot;https://www.humaaans.com/&quot;&gt;humaaans.com&lt;/a&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;امزج ونسق رسومات الأشخاص مع مكتبة تصميم&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ألوان&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;a href=&quot;https://coolors.co/&quot;&gt;coolors.co&lt;/a&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;مولد مخططات الألوان فائق السرعة !&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;div class=&quot;title&quot;&gt;&lt;strong&gt;الاتجاهات&lt;/strong&gt;&lt;/div&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;a href=&quot;https://fr.pinterest.com&quot;&gt;بينترست&lt;/a&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;اكتشاف بصري للأفكار: صور، فيديوهات، مجموعات موضوعية.&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;a href=&quot;https://dribbble.com&quot;&gt;المراوغة&lt;/a&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;منصة لتصميمي يشاركون أعمالهم ويتفاعلون.&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;div class=&quot;title&quot;&gt;&lt;strong&gt;UX/UI و Design Systems&lt;/strong&gt;&lt;/div&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;a href=&quot;https://material.io/&quot;&gt;Google Material Design&lt;/a&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;نظام تصميم جوجل لواجهات مستخدم موحدة وقابلة للتكيف&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;a href=&quot;https://developer.apple.com/design/human-interface-guidelines/&quot;&gt;مبادئ الواجهة البشرية لشركة Apple&lt;/a&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;توصيات آبل لتصميم تطبيقات iOS وmacOS بديهية.&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;a href=&quot;https://www.uxpin.com/&quot;&gt;UXPin&lt;/a&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;منصة تصميم وتعاون لإنشاء النماذج الأولية وأنظمة التصميم&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;a href=&quot;https://www.frontify.com/&quot;&gt;فرونتفي&lt;/a&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;منصة إدارة العلامة التجارية وأنظمة التصميم لضمان التماسك&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;a href=&quot;https://designsystemsrepo.com/design-systems/&quot;&gt;مستودع أنظمة التصميم&lt;/a&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;مجموعة موارد وأمثلة لأنظمة التصميم للإلهام&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;تطوير الواجهة الأمامية&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;a href=&quot;https://htmlcheatsheet.com&quot;&gt;htmlcheatsheet.com&lt;/a&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;ورقة غش HTML&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;a href=&quot;https://fontawesome.com&quot; target=&quot;&quot;_blank&quot;&gt;fontawesome.com&lt;/a&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;مكتبة الأيقونات&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;a href=&quot;https://www.toptal.com/designers/htmlarrows/symbols/&quot;&gt;toptal.com/designers/htmlarrows/symbols&lt;/a&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;أيقونات أصلية في HTML&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;a href=&quot;https://css-tricks.com/&quot;&gt;CSS-Tricks&lt;/a&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;ضروري لـ CSS، مع مقالات ودروس ونصائح الواجهة الأمامية الحديثة.&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;a href=&quot;https://www.frontendmentor.io/&quot;&gt;مرشد الواجهة الأمامية&lt;/a&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;تحديات كود الواجهة الأمامية المستندة إلى مشاريع حقيقية لتحسين مهاراتك.&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;a href=&quot;https://dev.to/&quot;&gt;Dev.to&lt;/a&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;مجتمع مطورين لمشاركة المقالات، الدروس والمشاريع.&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;a href=&quot;https://codepen.io/&quot;&gt;كودبين&lt;/a&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;محرر كود عبر الإنترنت ومجتمع لمشاركة مقتطفات من الكود والعروض التوضيحية&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;div class=&quot;title&quot;&gt;&lt;strong&gt;تطوير الواجهة الأمامية المدعوم بالذكاء الاصطناعي&lt;/strong&gt;&lt;/div&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;a href=&quot;https://v0.dev/&quot;&gt;v0.dev&lt;/a&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;v0 يحول الوصف بلغة الطبيعية إلى الكود وواجهة المستخدم.&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;a href=&quot;https://uizard.io/&quot;&gt;Uizard&lt;/a&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;Uizard يركز على تحويل النماذج (الصور، الرسومات) إلى كود HTML، CSS وReact.&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;a href=&quot;https://www.usegalileo.ai/explore&quot;&gt;usegalileo.ai&lt;/a&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;يسمح لك Galileo AI بوصف الواجهة التي تريدها بلغة طبيعية، وتقوم الذكاء الاصطناعي بإنشاء تصميمات Figma قابلة للتحرير.&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;a href=&quot;https://play.teleporthq.io/&quot;&gt;TeleportHQ&lt;/a&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;TeleportHQ هي منصة تطوير الواجهة الأمامية منخفضة الكود تستخدم الذكاء الاصطناعي لمساعدتك على بناء ونشر مواقع ويب بصريًا.&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://microk8s.io/docs/&quot;&gt;وثيقة رسمية لـ microk8s&lt;/a&gt;+&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_تثبيت_حزمة_microk8s&quot;&gt;تثبيت حزمة microk8s:&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_gradle_kotlin_dsl&quot;&gt;Gradle-Kotlin-DSL:&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;NotImplementedException NotImplementedError، فائدة للاختبارات، يسمح بمعرفة مكاننا، وسبب الفشل.&lt;br&gt;
لم يتم تنفيذه بعد، يسمح برمي الاستثناء المناسب.&lt;br&gt;
Il y a :&lt;br&gt;
&lt;a href=&quot;http://commons.apache.org/proper/commons-lang/javadocs/api-release/org/apache/commons/lang3/NotImplementedException.html&quot;&gt;org.apache.commons.lang3.NotImplementedException&lt;/a&gt;&lt;br&gt;
&lt;a href=&quot;https://kotlinlang.org/api/latest/jvm/stdlib/kotlin/-not-implemented-error/&quot;&gt;kotlin.NotImplementedError&lt;/a&gt;+&lt;/p&gt;
&lt;/div&gt;

&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_روابط_interserver_net&quot;&gt;روابط: &lt;a href=&quot;https://www.interserver.net/tips/kb/extract-tar-gz-files-using-linux-command-line/&quot;&gt;interserver.net&lt;/a&gt;&lt;/h4&gt;

&lt;/div&gt;

&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_hackernoon_com&quot;&gt;&lt;a href=&quot;https://hackernoon.com/dont-install-postgres-docker-pull-postgres-bee20e200198&quot;&gt;hackernoon.com&lt;/a&gt;&lt;/h4&gt;

&lt;/div&gt;

&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code&gt;----
----
$ ./gradlew -Pparam_component=CUSTOM
----
----&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_مصادر&quot;&gt;مصادر:&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;*https://xenovation.com/blog/source-control-management/git/how-to-change-remote-git-repository[زينوفاشن] *https://intellipaat.com/community/3102/git-show-remote-url-how-can-i-determine-the-url-that-a-local-git-repository-was-originally-cloned-from[إنتلبيت]&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_تغيير_المستودع_البعيد_في_git&quot;&gt;تغيير المستودع البعيد في Git&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;عرض عنوان URL للمستودع البعيد الحالي&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code&gt;----
----
$ wget -r -k -np http://site.com/docs/manual/
----

لتحديد مجلد الوجهة أضف الوسيطة -P ثم أعطِ المسار.
----&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_روابط_etcher&quot;&gt;روابط: &lt;a href=&quot;https://www.balena.io/etcher/&quot;&gt;etcher&lt;/a&gt;&lt;/h4&gt;

&lt;/div&gt;

&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_روابط_askubuntu&quot;&gt;روابط: &lt;a href=&quot;https://askubuntu.com/questions/86849/how-to-unzip-a-zip-file-from-the-terminal&quot;&gt;askubuntu&lt;/a&gt;&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;إذا كنت ترغب في الاستخراج إلى مجلد وجهة معين، يمكنك استخدام : &lt;code&gt;` $ unzip ملف.zip -d مجلد_الوجهة &lt;/code&gt;` إذا كانت المجلدات المصدر والوجهة متطابقة، يمكنك ببساطة: &lt;code&gt;` $ unzip file.zip &lt;/code&gt;`&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_الروابط_stackexchange&quot;&gt;الروابط: &lt;a href=&quot;https://unix.stackexchange.com/questions/72661/show-sum-of-file-sizes-in-directory-listing&quot;&gt;stackexchange&lt;/a&gt;&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code&gt;----
----
$ du -ach --exclude &quot;./.*&quot; /home/troll/
----
----&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_حذف_فرع_على_github&quot;&gt;حذف فرع على GitHub&lt;/h4&gt;

&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_رابط_gist&quot;&gt;رابط: &lt;a href=&quot;https://gist.github.com/cheroliv/921a13ed23ae6d4d66af8d43dd536987&quot;&gt;gist&lt;/a&gt;&lt;/h4&gt;

&lt;/div&gt;

&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;لماذا asciidoc ou markdown ? هنا، أتوجه نحو asciidoc، لأن لدي بالفعل بعض tickets écrits في asciidoc.&lt;br&gt;
Asciidoc هي لغة ترميز تسمح بإنتاج المحتوى مع إضافة تنسيق يحافظ على النص قابلًا للقراءة من قبل إنسان.&lt;br&gt;
هذه طريقة لتوحيد معالجة النصوص للمحتويات البسيطة دون برامج إضافية.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;div class=&quot;title&quot;&gt;روابط :&lt;/div&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://blog.oxiane.com/2018/06/13/asciidoc-documentation-as-code/&quot;&gt;@jmdoudoux على موقع blog.oxiane.com، window=&quot;_blank&lt;/a&gt;[asciidoc]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://powerman.name/doc/asciidoc&quot; target=&quot;&quot;_blank&quot;&gt;powerman.name&lt;/a&gt;[asciidoc]&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;لتثبيت حزمة دبيان من ملف .deb عبر سطر الأوامر.&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;$ sudo dpkg -i /chemin/du/fichier/deb/&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;انظر هنا للhttps://unix.stackexchange.com/questions/159094/how-to-install-a-deb-file-by-dpkg-i-or-by-apt[مرجع]+&lt;/p&gt;
&lt;/div&gt;

&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;في مشروع تطبيق يُدار بواسطة مدير البناء Gradle&lt;br&gt;
إنه من الأفضل أن تكون هناك رؤية لجميع المجلدات&lt;br&gt;
مشارك في تطوير التطبيق,&lt;br&gt;
مثل مجلدات الموارد التي ليست&lt;br&gt;
في المسارات بالاتفاق&lt;br&gt;
على سبيل المثال أريد أن يكون المجلد src/jbake,&lt;br&gt;
ليكون مرئيًا كـ ‘resource folder’،&lt;br&gt;
من الممكن أن يتم ذلك عن طريق الدخول إلى إعدادات المشروع,&lt;br&gt;
في معالجات الـIDE. ومع ذلك، لا يتم حفظ هذا الخيار عند إعادة التحميل التالية&lt;br&gt;
من مشروع Gradle في بيئة التطوير المتكاملة. لتطبيق هذه الإعدادات بشكل دائم&lt;br&gt;
الحل هو تجاوز تكوين مسارات المصادر&lt;br&gt;
في ملف التكوين build.gradle كما في الأسطر 18، 19، 20 و21 :&lt;br&gt;
build.gradle&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-groovy&quot; data-lang=&quot;groovy&quot;&gt;plugins {
    id &quot;java&quot;
    id &quot;groovy&quot;
    id &quot;org.jbake.site&quot; version &quot;5.0.0&quot;
    id &quot;org.ajoberstar.git-publish&quot; version &quot;2.1.1&quot;
}
repositories {
    mavenCentral()
    jcenter()
}
group project_group
version project_version
sourceSets {
    main {
        java { srcDirs = [] }
        groovy { srcDirs =[&quot;src/main/java&quot;, &quot;src/main/groovy&quot;] }
        resources {
            srcDirs =[
                    &quot;src/main/resources&quot;,
                    &quot;src/jbake&quot;//in order to get site src content in the IDE
            ]
        }
    }
    test {
        java { srcDirs = [] }
        groovy { srcDirs =[&quot;src/test/java&quot;, &quot;src/test/groovy&quot;] }
    }
}
test {
    useJUnitPlatform()
}
configurations {
    ivy
}
dependencies {
    ivy &quot;org.apache.ivy:ivy:$ivy_version&quot;
    implementation &quot;org.codehaus.groovy:groovy-all:$groovy_version&quot;
    implementation &quot;org.asciidoctor:asciidoctor-java-integration:$asciidoctor_java_integration_version&quot;
    implementation &quot;org.freemarker:freemarker:$freemarker_version&quot;
    testImplementation &quot;org.junit.jupiter:junit-jupiter-api:$junit5_version&quot;
    testRuntimeOnly &quot;org.junit.jupiter:junit-jupiter-engine:$junit5_version&quot;
}
gitPublish {
    repoUri = github_pages_blog_repository
    branch = git_branch
    contents {
        from(file(jbake_content_from)) {
            into jbake_content_to
        }
    }
}
tasks.withType(GroovyCompile) {
    groovyClasspath += configurations.ivy
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;موضوع التذكرة هو تكوين سكريبت بناء Gradle.&lt;br&gt;
أريد أن أستطيع استخدام برنامج نصي Groovy دون الحاجة للإشارة&lt;br&gt;
إلى مشروع Gradle الذي ربطته به&lt;br&gt;
أريد أن أكون قادرًا على تشغيل هذا البرنامج النصي Groovy خارج Gradle&lt;br&gt;
بدون أن تكون تعليقات ivy لاسترداد الاعتمادات الخارجية&lt;br&gt;
لا يتسببون في مشكلات الأداء أو التجميع&lt;br&gt;
من سكريبت بناء Gradle.&lt;br&gt;
لإيضاح الاعتماد على التكوين، أستند إلى سكريبتين:&lt;br&gt;
سكريبت بناء Gradle وسكريبت Groovy&lt;br&gt;
يحتوي نص جروفي في البداية على السطر 2،&lt;br&gt;
تعليم لاعتماد خارجي&lt;br&gt;
باستخدام مدير التبعية Ivy.&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-Groovy&quot; data-lang=&quot;Groovy&quot;&gt;#!/usr/bin/env groovy
@Grab(&quot;commons-io:commons-io:2.6&quot;)

import org.apache.commons.io.FileUtils

static String getSeparator() {
    System.getProperty(&quot;file.separator&quot;)
}

String from = &quot;${System.getProperty(&quot;user.home&quot;)}${separator}.config${separator}transmission${separator}torrents&quot;
String to = &quot;${System.getProperty(&quot;user.home&quot;)}${separator}Documents${separator}torrents_completed&quot;

File fromDlDir = new File(&quot;${System.getProperty(&quot;user.home&quot;)}${separator}Téléchargements&quot;)
File fromDir = new File(from)
File toDir = new File(to)

Collection&amp;lt;File&amp;gt; torrentFiles = FileUtils.listFiles(
        fromDir,
        [&quot;torrent&quot;] as String[],
        false)
torrentFiles.addAll(FileUtils.listFiles(
        fromDlDir,
        [&quot;torrent&quot;, &quot;torrent.added&quot;] as String[],
        false))


torrentFiles.empty ?: torrentFiles.each { it -&amp;gt;
    FileUtils.copyFileToDirectory(it, toDir)
}
println torrentFiles.size()&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;في ملف build.gradle، الآن لنرى كيف نحقق الانسجام&lt;br&gt;
كلا مديري التبعيات, Ivy و Gradle. الاتفاق بين الاثنين يتم على الأسطر :&lt;br&gt;
26, 30, 37, 38 et 39&lt;br&gt;
وبالتالي يمكنني تشغيل سكريبت Groovy الخاص بي يدويًا&lt;br&gt;
ولا يعوق تجميع Gradle بسبب @Grab.&lt;br&gt;
لا يلزم توفير تبعيات نص Groovy في Gradle.&lt;br&gt;
من ناحية أخرى لا يمكنني تشغيل البرنامج النصي Groovy من Gradle.&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-Groovy&quot; data-lang=&quot;Groovy&quot;&gt;plugins {
    id &quot;java&quot;
    id &quot;groovy&quot;
}

repositories {
    mavenCentral()
    jcenter()
}

sourceSets {
    main {
        java { srcDirs = [] }
        groovy { srcDirs =[&quot;src/main/java&quot;, &quot;src/main/groovy&quot;] }
        resources {
            srcDirs =[&quot;src/main/resources&quot;]
        }
    }
    test {
        java { srcDirs = [] }
        groovy { srcDirs =[&quot;src/test/java&quot;, &quot;src/test/groovy&quot;] }
    }
}

configurations {
    ivy
}

dependencies {
    ivy &quot;org.apache.ivy:ivy:$ivy_version&quot;
    implementation &quot;org.codehaus.groovy:groovy-all:$groovy_version&quot;
}



tasks.withType(GroovyCompile) {
    groovyClasspath += configurations.ivy
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مرجع التذكرة  علىhttps://stackoverflow.com/a/18174033/837404[ستاك أوفرفلو]&lt;/p&gt;
&lt;/div&gt;

&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_الppmc&quot;&gt;الPPMC&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://fr.wikipedia.org/wiki/Plus_petit_commun_multiple&quot;&gt;wiki PPMC أو أصغر مضاعف مشترك&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;AlgebraUtils.groovy&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-groovy&quot; data-lang=&quot;groovy&quot;&gt;package com.cheroliv.misc

import groovy.transform.CompileStatic

@CompileStatic
class AlgebraUtils {

    /**
     * Great common divisor
     * Plus grand commun diviseur(pgcd)
     * Great Common Divisor
     * @param a
     * @param b
     * @return
     */
    static Integer gcd(Integer a, Integer b) {
        !b ? a : gcd(b, a % b)
    }


    /**
     * Least common multiple
     * Plus petit commun multiplicateur(ppmc)
     * @param a
     * @param b
     * @return
     */
    static BigInteger lcm(Integer a, Integer b) {
        (a * b / gcd(a, b)) as BigInteger
    }

    static void main(String... args) {
        Integer a = 96
        Integer b = 28
        println &quot;gcd($a, $b) = ${gcd(a, b)}&quot;
        a = 790
        b = 990
        println &quot;lcm($a, $b) = ${lcm(a, b)}&quot;
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;النتيجة:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;القاسم المشترك الأكبر(96, 28) = 4 أصغر مضاعف مشترك(790, 990) = 78210&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;أنا أبحث عن ملفات حسب معايير الاسم: قائمة الملفات التي لها الامتداد .h أو .cpp&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;$ find . -name &#39;*.h&#39; -o -name &#39;*.cpp&#39; + +&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;قائمة الملفات التي لها امتداد .h و .cpp&lt;br&gt;
يتم حفظ النتيجة في الملف list_of_txt_files.list&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;$ find . -name &#39;*.h&#39; -o -name &#39;*.cpp&#39; -print &amp;gt; list_of_txt_files.list&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;أنا أبحث عن قائمة الملفات التي امتدادها .chm&lt;br&gt;
وأنا أدمّر هذه القائمة.&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;$ find . -name &quot;*.chm&quot; -type f -delete&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_تحليل_وجمع_المتطلبات&quot;&gt;تحليل وجمع المتطلبات&lt;/h3&gt;

&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_حدد_إدارة_المشروع&quot;&gt;حدد إدارة المشروع&lt;/h3&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;../../diagram/definir_projet.png&quot; alt=&quot;definir la gestion de projet&quot;&gt;
&lt;/div&gt;
